import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table as stored in SQLite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  next_run_at: number | null;
  created_at: string;
  updated_at: string;
}

/** The public job shape returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export const JOB_COLUMNS = `seq, id, status, input, steps, fail_attempts, attempts, progress_completed,
  result_output, error, idempotency_key, next_run_at, created_at, updated_at`;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress_completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  next_run_at INTEGER,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
CREATE TABLE IF NOT EXISTS heartbeat (
  name TEXT PRIMARY KEY,
  at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` inside a write transaction that takes the database write lock up front. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
  return result;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export const nowIso = (): string => new Date().toISOString();
export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const MAX_INPUT_LENGTH = 1000;

function isIntegerIn(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Validates a parsed request body and applies defaults. Collects every offending field. */
export function validateSubmission(body: unknown): ValidationResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const record = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'is not an allowed field' });
  }

  const input = record.input;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'is required and must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  }

  const steps = record.steps === undefined ? 5 : record.steps;
  if (!isIntegerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });

  const failAttempts = record.failAttempts === undefined ? 0 : record.failAttempts;
  if (!isIntegerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { JOB_COLUMNS, nowIso, openDatabase, toJob, transaction, type Job, type JobRow } from './db.ts';
import { validateSubmission, type FieldError, type Submission } from './validate.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 16 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectById = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`);
const selectByKey = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`);
const selectAll = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`);
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?)`,
);
const selectWorkerHeartbeat = db.prepare(`SELECT at FROM heartbeat WHERE name = 'worker'`);

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

type SubmitOutcome = { status: 200 | 201; job: Job } | { status: 409 };

function submit(submission: Submission, key: string | null): SubmitOutcome {
  return transaction(db, () => {
    if (key !== null) {
      const existing = selectByKey.get(key) as unknown as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === submission.input &&
          existing.steps === submission.steps &&
          existing.fail_attempts === submission.failAttempts;
        return same ? { status: 200, job: toJob(existing) } : { status: 409 };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    insertJob.run(id, submission.input, submission.steps, submission.failAttempts, key, now, now);
    return { status: 201, job: toJob(selectById.get(id) as unknown as JobRow) };
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    if (typeof rawKey === 'string' && IDEMPOTENCY_KEY.test(rawKey)) key = rawKey;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const raw = await readBody(req);
  const rawType = req.headers['content-type'];
  const contentType = (typeof rawType === 'string' ? rawType : '').split(';')[0]!.trim().toLowerCase();
  let submission: Submission | undefined;
  if (raw === undefined) {
    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (contentType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    let parsed: unknown;
    let parseOk = true;
    try {
      parsed = JSON.parse(raw);
    } catch {
      parseOk = false;
      fields.push({ field: 'body', message: 'is not valid JSON' });
    }
    if (parseOk) {
      const result = validateSubmission(parsed);
      if (result.ok) submission = result.value;
      else fields.push(...result.fields);
    }
  }

  if (fields.length > 0 || submission === undefined) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
  }

  const outcome = submit(submission, key);
  if (outcome.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.status, outcome.job);
}

function workerIsUp(): boolean {
  const row = selectWorkerHeartbeat.get() as unknown as { at: number } | undefined;
  return row !== undefined && Date.now() - Number(row.at) <= WORKER_FRESH_MS;
}

function route(req: IncomingMessage, res: ServerResponse): void | Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  const methodNotAllowed = (allow: string): void => {
    res.setHeader('allow', allow);
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
  };

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed('GET');
    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const jobs = (selectAll.all() as unknown as JobRow[]).map(toJob);
      return send(res, 200, { jobs });
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed('GET, POST');
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = selectById.get(id) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => route(req, res))
    .catch((err: unknown) => {
      console.error('request failed:', err);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal error.');
    });
});

server.on('error', (err) => {
  console.error(`server failed to listen on ${port}: ${err.message}`);
  process.exit(1);
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
process.on('SIGTERM', () => {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
});
import { setTimeout as sleep } from 'node:timers/promises';
import { JOB_COLUMNS, nowIso, openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
/** Total attempts per job, including the first. */
const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must be between 250 and 2000 ms. */
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

const selectDue = db.prepare(
  `SELECT id FROM jobs WHERE status = 'queued' AND (next_run_at IS NULL OR next_run_at <= ?) ORDER BY seq ASC LIMIT 1`,
);
const claim = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, next_run_at = NULL, updated_at = ?
   WHERE id = ? AND status = 'queued'`,
);
const selectById = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`);
const setProgress = db.prepare(
  `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const complete = db.prepare(
  `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const requeueWithDelay = db.prepare(
  `UPDATE jobs SET status = 'queued', progress_completed = 0, error = NULL, next_run_at = ?, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const failPermanently = db.prepare(
  `UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = 'transient failure', updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
/** Returns an interrupted attempt to the queue without counting it, so it is processed again as the same attempt. */
const requeueInterrupted = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const recoverRunning = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ?
   WHERE status = 'running'`,
);
const writeHeartbeat = db.prepare(
  `INSERT INTO heartbeat (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`,
);
const clearHeartbeat = db.prepare(`DELETE FROM heartbeat WHERE name = 'worker'`);

function beat(): void {
  try {
    writeHeartbeat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/** Claims the oldest queued job that is due, marking it running and counting the new attempt. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const due = selectDue.get(Date.now()) as unknown as { id: string } | undefined;
    if (!due) return undefined;
    claim.run(nowIso(), due.id);
    return selectById.get(due.id) as unknown as JobRow;
  });
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: fails at the first step, before any progress.
  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) {
      requeueInterrupted.run(nowIso(), job.id);
      return;
    }
    transaction(db, () => {
      if (attempt < MAX_ATTEMPTS) requeueWithDelay.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
      else failPermanently.run(nowIso(), job.id);
    });
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      requeueInterrupted.run(nowIso(), job.id);
      return;
    }
    setProgress.run(step, nowIso(), job.id);
  }
  complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

function onSignal(): void {
  stopping = true;
}

process.on('SIGINT', onSignal);
process.on('SIGTERM', onSignal);

// Anything left "running" belonged to a worker that died. Process it again.
transaction(db, () => recoverRunning.run(nowIso()));
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNext();
    if (job) await runAttempt(job);
    else await sleep(POLL_MS);
  } catch (err) {
    console.error('worker loop error:', err);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
try {
  clearHeartbeat.run();
} catch {
  // best effort; the heartbeat goes stale within 3 s anyway
}
db.close();
console.log('worker stopped');
