<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="number" step="any" placeholder="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="number" step="any" placeholder="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit</button>
  </form>

  <div data-testid="form-error" role="alert" id="form-error"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    (function () {
      var form = document.getElementById('job-form');
      var inputEl = form.querySelector('[data-testid="job-input"]');
      var stepsEl = form.querySelector('[data-testid="job-steps"]');
      var failEl = form.querySelector('[data-testid="job-fail-attempts"]');
      var submitEl = form.querySelector('[data-testid="job-submit"]');
      var errorEl = document.getElementById('form-error');
      var listEl = document.getElementById('job-list');

      function el(tag, testid, text) {
        var node = document.createElement(tag);
        if (testid) node.setAttribute('data-testid', testid);
        if (text !== undefined) node.textContent = text;
        return node;
      }

      function describeRejection(status, data) {
        var err = data && data.error;
        if (!err) return 'Request failed with status ' + status + '.';
        var text = err.message || 'Request failed.';
        if (Array.isArray(err.fields) && err.fields.length > 0) {
          text += ' ' + err.fields.map(function (f) { return f.field + ': ' + f.message; }).join('; ');
        }
        return text;
      }

      form.addEventListener('submit', async function (event) {
        event.preventDefault();
        var body = { input: inputEl.value };
        if (stepsEl.value.trim() !== '') body.steps = Number(stepsEl.value);
        if (failEl.value.trim() !== '') body.failAttempts = Number(failEl.value);

        submitEl.disabled = true;
        try {
          var res = await fetch('/api/jobs', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify(body),
          });
          var data = await res.json().catch(function () { return null; });
          if (res.ok) {
            errorEl.textContent = '';
            inputEl.value = '';
            stepsEl.value = '';
            failEl.value = '';
            refresh();
          } else {
            errorEl.textContent = describeRejection(res.status, data);
          }
        } catch (err) {
          errorEl.textContent = 'Could not reach the server: ' + err.message;
        } finally {
          submitEl.disabled = false;
        }
      });

      function render(jobs) {
        listEl.replaceChildren.apply(listEl, jobs.map(function (job) {
          var item = el('li', 'job-item');
          item.setAttribute('data-job-id', job.id);
          var status = el('span', 'job-status', job.status);
          status.className = 'status-' + job.status;
          var output = '';
          if (job.status === 'completed' && job.result) output = job.result.output;
          else if (job.status === 'failed' && job.error) output = job.error;
          item.append(
            status,
            el('span', 'job-progress', job.progress.completed + '/' + job.progress.total),
            el('span', 'job-result', output),
            el('span', 'id', job.id),
          );
          return item;
        }));
      }

      async function refresh() {
        try {
          var res = await fetch('/api/jobs');
          if (!res.ok) return;
          var data = await res.json();
          render(data.jobs);
        } catch (err) {
          // Server unreachable; keep the last rendered list and try again.
        }
      }

      refresh();
